package com.pixilife.android;
import android.content.*;import java.io.*;import java.net.*;import org.json.*;
public final class VisionClient {
 public interface Callback{void done(String answer,String error);}
 public static void analyze(Context c,String question,Callback cb){new Thread(()->{HttpURLConnection h=null;try{File f=new File(c.getFilesDir(),"latest_vision.jpg");if(!f.exists())throw new Exception("La cámara todavía está preparando el primer fotograma");byte[] jpeg=new byte[(int)f.length()];try(FileInputStream in=new FileInputStream(f)){int at=0,n;while(at<jpeg.length&&(n=in.read(jpeg,at,jpeg.length-at))>0)at+=n;}android.content.SharedPreferences p=c.getSharedPreferences("pixi",Context.MODE_PRIVATE);h=(HttpURLConnection)new URL(p.getString("worker_url","https://pixi-openai.gabostorecodex.workers.dev")+"/vision").openConnection();h.setRequestMethod("POST");h.setConnectTimeout(15000);h.setReadTimeout(45000);h.setDoOutput(true);h.setRequestProperty("Content-Type","application/json");h.setRequestProperty("X-Pixi-Token",p.getString("access_token","Gabo@22622"));JSONObject o=new JSONObject();o.put("question",question);o.put("image","data:image/jpeg;base64,"+android.util.Base64.encodeToString(jpeg,android.util.Base64.NO_WRAP));try(OutputStream out=h.getOutputStream()){out.write(o.toString().getBytes("UTF-8"));}InputStream stream=h.getResponseCode()<400?h.getInputStream():h.getErrorStream();BufferedReader r=new BufferedReader(new InputStreamReader(stream,"UTF-8"));StringBuilder s=new StringBuilder();String line;while((line=r.readLine())!=null)s.append(line);JSONObject j=new JSONObject(s.toString());String a=j.optString("reply","");if(a.isEmpty())throw new Exception(j.optString("error","No recibí respuesta visual"));cb.done(a,null);}catch(Exception e){cb.done(null,e.getMessage());}finally{if(h!=null)h.disconnect();}}).start();}
 private VisionClient(){}
}
